<?php
namespace App\Modules\Orders\Application;
use App\Models\User;use App\Modules\Inventory\Domain\Models\InventoryBalance;use App\Modules\Orders\Domain\Enums\ReservationStatus;use App\Modules\Orders\Domain\Enums\SalesOrderStatus;use App\Modules\Production\Domain\Models\ProductionOrder;
class ReopenProductionDemand {public function __construct(private readonly RebuildOrderDemand $rebuild){}public function execute(ProductionOrder $production,User $actor):void{$production->loadMissing(['orderAllocations.salesOrderLine.reservations','orderAllocations.salesOrderLine.order']);foreach($production->orderAllocations as $allocation){$line=$allocation->salesOrderLine;foreach($line->reservations->where('production_order_allocation_id',$allocation->id)->where('status',ReservationStatus::Active) as $reservation){$balance=InventoryBalance::query()->where('presentation_id',$reservation->presentation_id)->lockForUpdate()->sole();$balance->update(['reserved_quantity'=>max(0,(float)$balance->reserved_quantity-(float)$reservation->quantity)]);$reservation->update(['status'=>ReservationStatus::Released,'released_at'=>now()]);}$line->update(['produced_quantity'=>max(0,(float)$line->produced_quantity-(float)$allocation->produced_quantity),'reserved_quantity'=>max(0,(float)$line->reserved_quantity-(float)$allocation->reserved_quantity)]);$allocation->update(['produced_quantity'=>0,'reserved_quantity'=>0]);$order=$line->order;$from=$order->status;$order->update(['status'=>SalesOrderStatus::PendingProduction]);if($from!==SalesOrderStatus::PendingProduction)$order->histories()->create(['from_status'=>$from->value,'to_status'=>SalesOrderStatus::PendingProduction->value,'changed_by'=>$actor->id,'changed_at'=>now(),'notes'=>"Reversión de {$production->document_number}."]);$this->rebuild->execute($order->fresh('lines.presentation'));}}}
